// Stand-in for the PostgreSQL node: returns the rows that
// SELECT title, genre, watch_minutes, watch_started
//   FROM watch_events WHERE user_id = $1
// would return for this subscriber.
const trigger = $input.first().json.body;
const rows = [
  { title: 'Monsoon Wedding',  genre: 'drama',    watch_minutes: 118, watch_started: '2026-07-26T20:10:00Z' },
  { title: 'Andaz Apna Apna',  genre: 'comedy',   watch_minutes: 42,  watch_started: '2026-07-27T21:40:00Z' },
  { title: 'Sholay',           genre: 'drama',    watch_minutes: 96,  watch_started: '2026-07-29T19:05:00Z' },
  { title: 'Drishyam',         genre: 'thriller', watch_minutes: 61,  watch_started: '2026-07-31T22:15:00Z' },
  { title: 'Zindagi Milegi',   genre: 'drama',    watch_minutes: 134, watch_started: '2026-08-01T18:30:00Z' },
];
return rows.map(r => ({ json: { user_id: trigger.user_id, plan: trigger.plan, ...r } }));

// compute_engagement_summary — runs once for all items
const rows = $input.all();
const trigger = $('Churn Event Webhook').first().json.body;

const watchMins = rows.map(r => r.json.watch_minutes);
const avgWatch = watchMins.reduce((a, b) => a + b, 0) / watchMins.length;

const genreCounts = {};
rows.forEach(r => {
  const g = r.json.genre || 'other';
  genreCounts[g] = (genreCounts[g] || 0) + 1;
});
const topGenre = Object.entries(genreCounts).sort(([,a],[,b]) => b - a)[0][0];

const lastWatch = Math.max(...rows.map(r => new Date(r.json.watch_started).getTime()));
const daysSince = Math.floor((Date.now() - lastWatch) / 86400000);

return [{ json: {
  user_id: trigger.user_id,
  plan: trigger.plan,
  churn_score: trigger.churn_score,
  avg_watch_mins: Number(avgWatch.toFixed(1)),
  top_genre: topGenre,
  days_since_last_watch: daysSince,
  sessions: rows.length,
} }];
